from pathlib import Path

idx = Path('index.html')
sw = Path('sw.js')
readme = Path('README.md')

s = idx.read_text(encoding='utf-8')

# 1) Version
old = "const BUILD = 'V8.2.55';"
new = "const BUILD = 'V8.2.56';"
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new, 1)

# 2) Support section: add user manual alongside FAQ.
old = '<span class="acc-n"><b>지원 및 안내</b><span>도움말 · 자주 묻는 질문</span></span>'
new = '<span class="acc-n"><b>지원 및 안내</b><span>도움말 · 자주 묻는 질문 · 사용설명서</span></span>'
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new, 1)

faq_card = '''      <button class="toolcard" type="button" onclick="go('guide')"><span class="ic" data-ico="check"></span><span class="b"><b>도움말 · 자주 묻는 질문</b><span>설정 · 기록 · 알림 · 회복도구 · 마음프로 사용법</span></span><span class="go">열기</span></button>'''
manual_cards = faq_card + '''\n      <button class="toolcard" type="button" style="margin-top:9px" onclick="go('manual')"><span class="ic" data-ico="sprout"></span><span class="b"><b>사용설명서</b><span>처음 시작부터 기록 · 알림 · 안전한 사용까지 메뉴별 안내</span></span><span class="go">열기</span></button>'''
assert s.count(faq_card) == 1, s.count(faq_card)
s = s.replace(faq_card, manual_cards, 1)

# 3) Replace the former "next step" note and insert the full in-app manual.
marker = '''  <div class="note" style="margin-top:18px">도움말에 없는 기능은 다음 단계의 <b>사용설명서</b>에서 메뉴별로 더 자세히 안내합니다.</div>\n</section>\n\n  </div><!-- /view -->'''
manual = '''  <div class="note" style="margin-top:18px">짧은 답보다 메뉴 전체 흐름이 필요하면 <b>사용설명서</b>를 확인하세요.</div>\n  <button class="btn sec" type="button" style="margin-top:10px" onclick="go('manual')">사용설명서 열기</button>\n</section>\n\n<!-- ══════════ 사용설명서 ══════════ -->\n<section class="pg" id="p-manual">\n  <div class="sp" style="margin-bottom:11px"><h1 style="margin:0">사용설명서</h1><button class="tiny" style="color:var(--acc);font-weight:600" onclick="appBack('me')">← 내 정보 · 설정</button></div>\n  <p class="muted" style="margin:0 0 14px">오늘 한 걸음의 기능을 메뉴 순서대로 설명합니다. 필요한 항목만 펼쳐서 확인하세요.</p>\n  <div class="note" style="margin-bottom:14px"><b>기본 원칙</b><br>회복기록은 현재 기기 안에 저장됩니다. 앱 삭제·앱 데이터 삭제·기기 초기화 전에는 <b>기록 내보내기</b>를 먼저 권합니다. 이 앱은 치료나 응급서비스를 대신하지 않습니다.</div>\n\n  <div class="faq-list">\n    <details class="faq" open><summary>1. 처음 시작하기</summary><div class="faq-a">\n      <p><b>① 역할 선택</b> — 당사자 또는 가족·보호자를 고릅니다. 역할에 따라 보이는 문구와 일부 도구가 달라집니다.</p>\n      <p style="margin-top:8px"><b>② 회복 정보 설정</b> — 당사자 모드에서는 회복 영역과 시작일, 필요한 경우 회복 목표·지역·위험 시간대를 정합니다.</p>\n      <p style="margin-top:8px"><b>③ 홈 확인</b> — 설정을 마치면 홈에서 오늘 상태와 회복 흐름, 오늘 챙길 항목을 확인합니다.</p>\n      <p style="margin-top:8px"><b>④ 계획 만들기</b> — 회복도구 → 일정·알림에서 습관·생활·치료 일정을 정합니다.</p>\n      <p style="margin-top:8px"><b>⑤ 기록 돌아보기</b> — 나 → 내 발자취에서 저장한 기록과 변화 흐름을 확인합니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('home')">홈 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>2. 화면과 메뉴 구조</summary><div class="faq-a">\n      <p>하단 메뉴는 <b>홈 · 회복도구 · 헬프 · 마음프로</b>를 중심으로 사용합니다. 홈 오른쪽 위의 사람 모양 버튼을 누르면 <b>나</b>로 들어가 내 발자취와 내 정보·설정을 관리할 수 있습니다.</p>\n      <p style="margin-top:8px">관리자 기능은 일반 사용 메뉴와 분리되어 있으며, 관리자 상태일 때만 별도 메뉴가 표시됩니다.</p>\n    </div></details>\n\n    <details class="faq"><summary>3. 홈 — 오늘 상태를 한눈에 보기</summary><div class="faq-a">\n      <p>홈은 매일 가장 먼저 확인하는 화면입니다. 당사자 모드에서는 <b>회복일, 오늘의 상태, HALT, 복약·식사·잠</b>처럼 지금 챙길 항목을 한곳에서 확인합니다. 설정한 내용과 역할에 따라 보이는 항목은 달라질 수 있습니다.</p>\n      <p style="margin-top:8px">힘든 상태가 올라오면 홈과 위기 흐름에서 충동 대응, 호흡, 도움글, 사람 연결 등 필요한 기능으로 이어갈 수 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('home')">홈 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>4. 회복도구 — 계획 · 배우기 · 실천 · 자가점검</summary><div class="faq-a">\n      <p><b>내 계획</b> — 일정·알림에서 습관·생활·치료 일정을 관리합니다.</p>\n      <p style="margin-top:8px"><b>배우기</b> — 회복학습, 중독 Q&amp;A, 듣는 글을 이용합니다. 회복학습에는 12단계와 SMART Recovery 등 앱에 정리된 학습 콘텐츠가 포함됩니다.</p>\n      <p style="margin-top:8px"><b>실천하기</b> — 12단계 점검, 회복 실천도구, 충동일기, 미래의 나에게 등을 사용합니다. 가족·보호자 모드에서는 가족을 위한 도구 중심으로 구성이 달라집니다.</p>\n      <p style="margin-top:8px"><b>자가점검</b> — 현재 상태를 선별도구로 살펴보고 저장된 결과의 변화를 확인합니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('tools')">회복도구 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>5. 일정 · 알림 — 습관 · 생활 · 치료를 한곳에서</summary><div class="faq-a">\n      <p><b>습관</b>에서는 작은 실천을 만들고 오늘 했는지 체크합니다. 추천 습관을 그대로 사용하거나 수정해 시작할 수 있습니다.</p>\n      <p style="margin-top:8px"><b>생활 일정</b>에서는 위험한 시간대와 식사·잠 시간을 정합니다.</p>\n      <p style="margin-top:8px"><b>치료 일정</b>은 당사자 모드에서 복약, 처방, 외래와 반복 외래 일정을 관리합니다.</p>\n      <p style="margin-top:8px">Android 설치 앱에서는 알림 설정에서 실제 예약 상태를 확인합니다. 정확 알림을 사용하므로 화면이 꺼져 있어도 예약 시각에 알림이 오도록 구성되어 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('schedule')">일정 · 알림 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>6. 12단계 · 회복 실천도구 사용하기</summary><div class="faq-a">\n      <p><b>12단계 점검</b>에서는 1·4·8·9·10·11·12단계의 작성형 검토를 사용할 수 있습니다. 작성 중 초안은 기기에 저장되고, 완료해 저장한 기록은 내 발자취 → 실천기록에서 다시 확인합니다.</p>\n      <p style="margin-top:8px"><b>회복 실천도구</b>는 SMART Recovery의 4-Point를 순서대로 통과하는 단계가 아니라, 지금 필요한 영역을 골라 쓰는 구조입니다. 가치 우선순위 정하기, 의사결정 저울, 충동 다루기, 중독 생각과 거리두기, 상황·생각·감정 돌아보기, 생각 점검하기, 문제 해결하기, 삶의 균형 살펴보기, 건강한 관심사 찾기, 실천 목표 세우기 등을 필요에 따라 사용합니다.</p>\n      <p style="margin-top:8px">작성형 도구의 저장기록은 내 발자취 → 실천기록에서 확인합니다. 빠른 변화 준비도 점검처럼 저장하지 않는 도구도 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('smart-tools')">회복 실천도구 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>7. 자가점검 — 결과와 변화 확인하기</summary><div class="faq-a">\n      <p>자가점검은 <b>진단이 아니라 선별·참고 도구</b>입니다. 검사를 마치면 점수와 결과구간을 현재 기기에 저장할 수 있고, <b>내 발자취 → 자가점검</b>에서 검사별 이전 결과와 변화 흐름을 확인합니다.</p>\n      <p style="margin-top:8px">결과가 걱정되거나 일상 기능에 어려움이 있으면 점수만으로 판단하지 말고 전문가와 상의하세요.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('screening')">자가점검 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>8. 내 발자취 — 저장한 기록 다시 보기</summary><div class="faq-a">\n      <p>당사자 모드에서는 <b>감정 · 충동 · 하루 · 몸 · 다시 시작 · 실천기록 · 자가점검 · 통계</b>를 한곳에서 돌아봅니다. 가족·보호자 모드에서는 당사자의 충동·재발을 대신 기록하지 않도록 구성이 달라집니다.</p>\n      <p style="margin-top:8px">12단계와 회복 실천도구의 저장기록도 실천기록에서 상세 내용을 다시 열 수 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('rec')">내 발자취 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>9. 헬프 · 지금 위험해요 — 사람과 실제 자원 연결</summary><div class="faq-a">\n      <p><b>헬프</b>에는 헬프콜과 자조모임, 센터·병원처럼 실제 도움으로 연결되는 자원이 모여 있습니다. 자원 목록은 앱 설정에서 최신 목록을 다시 받을 수 있습니다.</p>\n      <p style="margin-top:8px"><b>지금 위험해요</b>는 충동이 매우 강하거나 즉시 도움이 필요한 때의 대응 흐름입니다. 생명이나 신체에 즉각적인 위험이 있으면 앱에 머물지 말고 <b>112 또는 119</b>, 가까운 응급의료기관 등 즉시 연결 가능한 도움을 이용하세요.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('help')">헬프 열기</button>\n      <button class="btn danger sm faq-go" type="button" onclick="go('panic')">지금 위험해요 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>10. 마음프로 — 앱 안내와 대화 기능</summary><div class="faq-a">\n      <p>마음프로는 회복학습과 앱 사용법을 안내하고 사용자가 직접 보낸 문장에 답합니다. 12단계·SMART Recovery·복약·외래·일정·알림·자가점검 같은 앱 기능 질문은 가능한 경우 앱에 들어 있는 내용과 연결 기능을 먼저 사용합니다.</p>\n      <p style="margin-top:8px"><b>내 발자취, 자가점검 점수, 12단계·회복 실천도구 기록은 자동으로 마음프로에 전송되지 않습니다.</b> 일반 대화에서 사용자가 직접 전송한 문장은 AI 답변 생성을 위해 서버로 전송됩니다.</p>\n      <p style="margin-top:8px">Android 설치 앱에서는 마음프로 답변 자동 읽기를 사용할 수 있고, “계속 읽어줘”, “그만 읽어” 같은 음성 명령은 앱 안에서 처리됩니다.</p>\n      <p style="margin-top:8px">마음프로는 치료자나 응급서비스를 대신하지 않습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('ai')">마음프로 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>11. 가족 · 보호자 모드</summary><div class="faq-a">\n      <p>가족·보호자 모드는 당사자의 회복기록을 대신 작성하는 화면이 아니라 <b>가족 자신의 안전, 경계, 대화, 대응계획과 생활 회복</b>을 돕는 방향으로 구성됩니다.</p>\n      <p style="margin-top:8px">가족을 위한 도구에서는 경계 세우기, 대화 준비, 다시 사용했을 때 내 대응계획과 내 생각·행동·생활을 돌보는 연습을 사용할 수 있습니다. 역할은 나 → 내 정보 · 설정 → 나에서 언제든 바꿀 수 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('me')">역할 설정 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>12. 내 정보 · 설정 — 설정, 백업, 앱 관리</summary><div class="faq-a">\n      <p><b>나</b>에서는 역할, 회복 영역·시작일·목표·지역 등 기본 정보를 관리합니다.</p>\n      <p style="margin-top:8px"><b>앱</b>에서는 자원 목록 새로 받기, 화면 밝기, 앱 새로고침·설치와 Android 마음프로 음성 설정을 관리합니다.</p>\n      <p style="margin-top:8px"><b>기록 관리</b>에서는 JSON 파일로 내보내기·불러오기와 전체 지우기를 할 수 있습니다. 다른 기기로 옮기거나 앱을 삭제하기 전에는 내보내기를 먼저 권합니다.</p>\n      <p style="margin-top:8px"><b>앱에 바라는 점</b>은 불편한 점이나 제안을 보내는 기능입니다. 작성 내용과 앱 버전만 전송되며 민감한 개인정보는 직접 적지 않는 것이 좋습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('me')">내 정보 · 설정 열기</button>\n    </div></details>\n\n    <details class="faq"><summary>13. Android 설치 앱 — 알림과 음성</summary><div class="faq-a">\n      <p>Android 설치 앱은 습관·생활·복약·외래 예약을 네이티브 알림으로 관리합니다. 정확 알림, 화면 OFF 상태 알림, 부팅 후 재예약이 연결되어 있습니다.</p>\n      <p style="margin-top:8px">알림이 오지 않으면 Android 알림 권한, 정확 알림 허용, 앱의 알림 예약 상태와 기기의 절전·배터리 제한을 확인하세요.</p>\n      <p style="margin-top:8px">마음프로 답변 자동 읽기와 이완 가이드는 Android 네이티브 TTS를 사용합니다. 일반 웹/PWA에서는 Android 전용 음성 기능이 표시되지 않을 수 있습니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('schedule')">알림 설정으로</button>\n    </div></details>\n\n    <details class="faq"><summary>14. 기록을 안전하게 보관하는 방법</summary><div class="faq-a">\n      <p>개인 회복기록은 기본적으로 현재 기기에 저장되므로 <b>정기적으로 기록 관리 → 파일로 내보내기</b>를 해두는 것이 가장 중요합니다.</p>\n      <p style="margin-top:8px">기존 앱 위에 업데이트하는 경우 같은 앱 데이터가 유지되도록 설계되어 있지만, 앱 삭제·앱 데이터 삭제·브라우저 데이터 삭제·기기 초기화는 기록 손실로 이어질 수 있습니다.</p>\n      <p style="margin-top:8px">불러오기는 백업 파일의 기록을 현재 앱에 복원하는 기능이므로, 중요한 기록이 있다면 현재 상태도 먼저 내보내 두는 편이 안전합니다.</p>\n      <button class="btn ghost sm faq-go" type="button" onclick="go('me')">기록 관리 열기</button>\n    </div></details>\n  </div>\n\n  <div class="note w" style="margin-top:18px">기능을 찾기 어렵거나 짧은 답이 필요하면 <b>지원 및 안내 → 도움말 · 자주 묻는 질문</b>을 함께 이용하세요.</div>\n  <button class="btn ghost" type="button" style="margin-top:10px" onclick="go('guide')">도움말 · 자주 묻는 질문 열기</button>\n</section>\n\n  </div><!-- /view -->'''
assert s.count(marker) == 1, s.count(marker)
s = s.replace(marker, manual, 1)

# Protected storage constants must not change.
assert "const KEY = 'ohg.v1';" in s
assert "const DATA_SCHEMA = 6;" in s
assert s.count('id="p-manual"') == 1
assert s.count("go('manual')") >= 2
idx.write_text(s, encoding='utf-8')

# 4) Service worker version/cache only.
w = sw.read_text(encoding='utf-8')
assert w.count("const APP_VERSION = 'V8.2.55';") == 1
assert w.count("const V = 'ohg-v8255-help-faq';") == 1
w = w.replace("const APP_VERSION = 'V8.2.55';", "const APP_VERSION = 'V8.2.56';", 1)
w = w.replace("const V = 'ohg-v8255-help-faq';", "const V = 'ohg-v8256-user-manual';", 1)
sw.write_text(w, encoding='utf-8')

# 5) README release note.
r = readme.read_text(encoding='utf-8')
entry = '''## V8.2.56 — 사용설명서\n- `내 정보 · 설정 → 지원 및 안내`에 `사용설명서`를 추가하고 기존 FAQ와 나란히 진입할 수 있게 했습니다.\n- 사용설명서는 처음 시작하기, 화면 구조, 홈, 회복도구, 일정·알림, 12단계·회복 실천도구, 자가점검, 내 발자취, 헬프·위기, 마음프로, 가족·보호자, 설정·백업, Android 알림·음성, 기록 보관 순서로 구성했습니다.\n- 설명은 현재 앱의 실제 메뉴와 연결 기능을 기준으로 작성하고, 주요 화면에는 바로가기 버튼을 제공합니다.\n- 개인정보처리방침은 다음 단계에서 실제 데이터 흐름을 다시 검증한 뒤 별도로 작성합니다.\n- `DATA_SCHEMA=6`, `ohg.v1`, 기존 기록형식, Android 정확알림·화면 OFF 알림·부팅 재예약·복약/외래/생활/습관 알림·네이티브 TTS·이완 TTS는 변경하지 않습니다.\n\n'''
assert not r.startswith('## V8.2.56')
readme.write_text(entry + r, encoding='utf-8')

print('V8.2.56 user manual patch applied')
